-- « Mesures » (LecteurSurveillanceMesures) : des evenements de procedure de la mesure 1500902 de PROC_MESIN.sql (joue avant
-- celui-ci, ordre des noms). Ses mesures sont toutes listees par PROC_MESIN : ce jeu n'en ajoute pas, il rattache ses evenements
-- a une mesure existante, active (ni rapport, ni sans suite, ni caducite). Les evenements de PROC_MESIN n'ont ni date maximale, ni
-- minimale, ni fixe : aucune echeance, ils ne sont pas dans cette file. Types de RIG_DEV (lu le 26/11/2026). Les insertions passent
-- par sp_executesql : elles lisent des colonnes que ce meme jeu ajoute.
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_MSINS') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_MSINS int NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_MAXI') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_MAXI datetime NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_MINI') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_MINI datetime NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_FIXE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_FIXE datetime NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE varchar(10) NULL;
IF COL_LENGTH('v2.MESURE', 'MSINS_DATE_DEPOT_RAPPORT') IS NULL ALTER TABLE v2.MESURE ADD MSINS_DATE_DEPOT_RAPPORT datetime NULL;
IF COL_LENGTH('v2.MESURE', 'MSINS_DATE_SANS_SUITE') IS NULL ALTER TABLE v2.MESURE ADD MSINS_DATE_SANS_SUITE datetime NULL;
IF COL_LENGTH('v2.MESURE', 'MSINS_DATE_CADUCITE') IS NULL ALTER TABLE v2.MESURE ADD MSINS_DATE_CADUCITE datetime NULL;

-- Deux codes : BANC9EXP a un code « expire » (BANC9X) -- il se traite ; BANC9OBS n'en a pas -- grise, en rouge
-- (DataGridMesures.cs:240-245).
EXEC sp_executesql N'
INSERT INTO v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR, R_CODEEVEPRO_LIBELLE_ECRAN, R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE) VALUES
    (''BANC9EXP'', N''Échéance du banc 9'', ''BANC9X''), (''BANC9OBS'', N''Observation du banc 9'', NULL),
    (''BANC9X'', N''Expiration du banc 9'', NULL);';

-- L'echeance = ISNULL(MAXI, ISNULL(MINI, FIXE)) au plus aujourd'hui (OPE_RECHERCHE_MES.cs:51) :
--   1900701 MAXI hier (dans la file) ; 1900702 MINI avant-hier, sans MAXI (dans la file, sans code d'expiration) ;
--   1900703 FIXE aujourd'hui (dans la file : « <= » aujourd'hui) ; jumeau refuse 1900704, MAXI demain ;
--   1900705 survenu (EVNPR_SURVENU = 1) et 1900706 delai expire (EVNPR_DELAI_EXPIRE = 1) : hors file ; jumeau accepte 1900701 ;
--   1900707 : MAXI demain mais MINI hier -- MAXI l'emporte (priorite MAXI, MINI, FIXE) : hors file ; jumeau accepte 1900702.
EXEC sp_executesql N'
INSERT INTO v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR, EVNPR_ID_MSINS, EVNPR_NUM_ORDRE, EVNPR_CODE_EVE_PRO, EVNPR_SURVENU, EVNPR_DELAI_EXPIRE,
                                    EVNPR_DATE_MAXI, EVNPR_DATE_MINI, EVNPR_DATE_FIXE) VALUES
    (1900701, 1500902, 11, ''BANC9EXP'', 0, 0, DATEADD(day, -1, @aujourdhui), NULL, NULL),
    (1900702, 1500902, 12, ''BANC9OBS'', 0, 0, NULL, DATEADD(day, -2, @aujourdhui), NULL),
    (1900703, 1500902, 13, ''BANC9EXP'', 0, 0, NULL, NULL, @aujourdhui),
    (1900704, 1500902, 14, ''BANC9EXP'', 0, 0, DATEADD(day, 1, @aujourdhui), NULL, NULL),
    (1900705, 1500902, 15, ''BANC9EXP'', 1, 0, DATEADD(day, -1, @aujourdhui), NULL, NULL),
    (1900706, 1500902, 16, ''BANC9EXP'', 0, 1, DATEADD(day, -1, @aujourdhui), NULL, NULL),
    (1900707, 1500902, 17, ''BANC9OBS'', 0, 0, DATEADD(day, 1, @aujourdhui), DATEADD(day, -1, @aujourdhui), NULL);',
    N'@aujourdhui datetime', @aujourdhui;

-- « Valider » (EcrivainSurveillanceMesures, PROC_SURVMES.gestes) : les colonnes que l'expiration et la creation des evenements
-- ecrivent (types de RIG_DEV, lu le 27/11/2026).
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE datetime NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NUMERO_SOURCE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NUMERO_SOURCE_EP_LIE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NUMERO_SOURCE_EP_LIE varchar(36) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_AVEC_PIECE_NUMERISE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_AVEC_PIECE_NUMERISE bit NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NATURE_DOC_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NOM_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NOM_DEPOSANT_GED varchar(100) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES bit NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_NATURE_DOC_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_NOM_DEPOSANT_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_NOM_DEPOSANT_GED varchar(100) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_CODE_EVE_PRO_FUTUR') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_CODE_EVE_PRO_FUTUR varchar(10) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_MOIS_DATE_MAXI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_MOIS_DATE_MAXI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_JOURS_DATE_MAXI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_JOURS_DATE_MAXI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_SEMAINES_DATE_MAXI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_SEMAINES_DATE_MAXI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_MOIS_DATE_MINI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_MOIS_DATE_MINI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_JOURS_DATE_MINI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_JOURS_DATE_MINI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_SEMAINES_DATE_MINI') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_SEMAINES_DATE_MINI tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_MOIS_DATE_FIXE') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_MOIS_DATE_FIXE tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_JOURS_DATE_FIXE') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_JOURS_DATE_FIXE tinyint NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_SEMAINES_DATE_FIXE') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_SEMAINES_DATE_FIXE tinyint NULL;

-- Les codes du geste. BANC9EXP expire en BANC9X : survenu (type S), piece numerisee pour une mesure (nature, type et nom du
-- deposant), futur BANC9F a 15 jours (les jours passent avant les semaines, Outils.cs:520-543) -- la date mini (1 semaine) tombe :
-- maxi avant mini (IEntiteJudiciaire.cs:185-190). BANC9EX2 expire en BANC9Y : futur BANC9G a 2 mois en date FIXE, qui l'emporte
-- sur la maxi de 10 jours ; BANC9G a une piece numerisee mais pas de nom de deposant (GererPiecesNum : survenu seulement).
-- BANC9EX3 expire en BANC9Z, dont le futur n'a aucun delai : pas de futur (:182-184). BANC9EX4 expire en BANC9ABS, absent de
-- la table : refus.
EXEC sp_executesql N'
UPDATE v2.CODE_EVE_PRO SET R_CODEEVEPRO_TYPE_EVE_PRO = ''S'', R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES = 1, R_CODEEVEPRO_NATURE_DOC_GED = ''NAT9'',
    R_CODEEVEPRO_TYPE_DEPOSANT_GED = ''TD9'', R_CODEEVEPRO_NOM_DEPOSANT_GED = N''Déposant du banc 9'', R_CODEEVEPRO_CODE_EVE_PRO_FUTUR = ''BANC9F'',
    R_CODEEVEPRO_JOURS_DATE_MAXI = 15, R_CODEEVEPRO_SEMAINES_DATE_MAXI = 3, R_CODEEVEPRO_SEMAINES_DATE_MINI = 1
WHERE R_CODEEVEPRO_VALEUR = ''BANC9X'';
UPDATE v2.CODE_EVE_PRO SET R_CODEEVEPRO_TYPE_EVE_PRO = ''F'' WHERE R_CODEEVEPRO_VALEUR = ''BANC9EXP'';
INSERT INTO v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR, R_CODEEVEPRO_LIBELLE_ECRAN, R_CODEEVEPRO_CODE_EVE_PRO_EXPIRE, R_CODEEVEPRO_TYPE_EVE_PRO,
    R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES, R_CODEEVEPRO_NATURE_DOC_GED, R_CODEEVEPRO_TYPE_DEPOSANT_GED, R_CODEEVEPRO_NOM_DEPOSANT_GED,
    R_CODEEVEPRO_CODE_EVE_PRO_FUTUR, R_CODEEVEPRO_MOIS_DATE_FIXE, R_CODEEVEPRO_JOURS_DATE_MAXI) VALUES
    (''BANC9EX2'', N''Échéance deux du banc 9'', ''BANC9Y'', ''F'', 0, NULL, NULL, NULL, NULL, NULL, NULL),
    (''BANC9EX3'', N''Échéance trois du banc 9'', ''BANC9Z'', ''F'', 0, NULL, NULL, NULL, NULL, NULL, NULL),
    (''BANC9EX4'', N''Échéance quatre du banc 9'', ''BANC9ABS'', ''F'', 0, NULL, NULL, NULL, NULL, NULL, NULL),
    (''BANC9Y'', N''Survenu deux du banc 9'', NULL, ''S'', 0, NULL, NULL, NULL, ''BANC9G'', 2, 10),
    (''BANC9Z'', N''Survenu trois du banc 9'', NULL, ''S'', 0, NULL, NULL, NULL, ''BANC9F'', NULL, NULL),
    (''BANC9F'', N''Futur du banc 9'', NULL, ''F'', 0, NULL, NULL, NULL, NULL, NULL, NULL),
    (''BANC9G'', N''Futur deux du banc 9'', NULL, ''F'', 1, ''NAT9G'', ''TD9G'', N''Nom G du banc 9'', NULL, NULL, NULL);';

-- Les evenements du geste, sur deux mesures LIBRES de PROC_MESIN.sql (1500903 : sa demande MESIN est validee ; 1500904 : sans
-- demande ni evenement) -- 1500902 est tenue par la demande MESIN D2615000941 en cours (refus du verrou). Pas 1500901 : le bloc 6
-- de PROC_MESIN.gestes (joue avant ces gestes) lui pose une caducite, elle sort de la file (mesure au banc le 27/11/2026).
-- 1900711 garde son numero source (SRC-1900711) ; 1900712 n'en a pas : un GUID lui est donne.
EXEC sp_executesql N'
INSERT INTO v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR, EVNPR_ID_MSINS, EVNPR_NUM_ORDRE, EVNPR_CODE_EVE_PRO, EVNPR_SURVENU, EVNPR_DELAI_EXPIRE,
                                    EVNPR_DATE_MAXI, EVNPR_DATE_MINI, EVNPR_DATE_FIXE, EVNPR_NUMERO_SOURCE) VALUES
    (1900711, 1500903, 1, ''BANC9EXP'', 0, 0, DATEADD(day, -1, @aujourdhui), NULL, NULL, ''SRC-1900711''),
    (1900712, 1500903, 2, ''BANC9EXP'', 0, 0, NULL, NULL, @aujourdhui, NULL),
    (1900713, 1500904, 1, ''BANC9EX2'', 0, 0, DATEADD(day, -3, @aujourdhui), NULL, NULL, NULL),
    (1900714, 1500904, 2, ''BANC9EX3'', 0, 0, NULL, DATEADD(day, -3, @aujourdhui), NULL, NULL),
    (1900715, 1500904, 3, ''BANC9EX4'', 0, 0, DATEADD(day, -4, @aujourdhui), NULL, NULL, NULL);',
    N'@aujourdhui datetime', @aujourdhui;
